func newAgentDecision() unsafe.Pointer { return unsafe.Pointer(new(agentdecision.AgentDecision)) }

func newNAgentDecision(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]agentdecision.AgentDecision, n)))
}

func ptrAgentDecision(p unsafe.Pointer, c int32) any {
	r := (*agentdecision.AgentDecision)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (**string)(unsafe.Pointer(&r.ProposalID))
	case 4:
		return (**string)(unsafe.Pointer(&r.ExceptionID))
	case 5:
		return (*string)(unsafe.Pointer(&r.DecidedByUserID))
	case 6:
		return (*string)(unsafe.Pointer(&r.Decision))
	case 7:
		return &r.Modifications
	case 8:
		return &r.ReasonCode
	case 9:
		return &r.Note
	case 10:
		return &r.TraceID
	case 11:
		return &r.Preview
	case 12:
		return &r.PreviewDigest
	case 13:
		return &r.PreviewReviewed
	case 14:
		return &r.PreviewTargetVersion
	case 15:
		return &r.CommitsAt
	case 16:
		return &r.CommittedAt
	case 17:
		return &r.UndoneAt
	case 18:
		return (**string)(unsafe.Pointer(&r.UndoneByUserID))
	case 19:
		return &r.CommitWorkflowID
	case 20:
		return &r.Version
	case 21:
		return &r.CreatedAt
	case 22:
		return &r.UpdatedAt
	}
	return nil
}

func valueAgentDecision(p unsafe.Pointer, c int32) any {
	r := (*agentdecision.AgentDecision)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		if r.ProposalID == nil {
			return nil
		}
		return string(*r.ProposalID)
	case 4:
		if r.ExceptionID == nil {
			return nil
		}
		return string(*r.ExceptionID)
	case 5:
		return string(r.DecidedByUserID)
	case 6:
		return string(r.Decision)
	case 7:
		if r.Modifications == nil {
			return nil
		}
		return r.Modifications
	case 8:
		return r.ReasonCode
	case 9:
		if r.Note == "" {
			return nil
		}
		return r.Note
	case 10:
		if r.TraceID == "" {
			return nil
		}
		return r.TraceID
	case 11:
		if r.Preview == nil {
			return nil
		}
		return *r.Preview
	case 12:
		if r.PreviewDigest == "" {
			return nil
		}
		return r.PreviewDigest
	case 13:
		return r.PreviewReviewed
	case 14:
		if r.PreviewTargetVersion == nil {
			return nil
		}
		return *r.PreviewTargetVersion
	case 15:
		if r.CommitsAt == nil {
			return nil
		}
		return *r.CommitsAt
	case 16:
		if r.CommittedAt == nil {
			return nil
		}
		return *r.CommittedAt
	case 17:
		if r.UndoneAt == nil {
			return nil
		}
		return *r.UndoneAt
	case 18:
		if r.UndoneByUserID == nil {
			return nil
		}
		return string(*r.UndoneByUserID)
	case 19:
		if r.CommitWorkflowID == "" {
			return nil
		}
		return r.CommitWorkflowID
	case 20:
		return r.Version
	case 21:
		return r.CreatedAt
	case 22:
		return r.UpdatedAt
	}
	return nil
}

